/* Native HFS traversal and inspection, with bounded depth and no link following. */
#include "mac-files.h"
static const char *pattern;static char kind;static int explicit_depth,maxdepth=8,all,summarize,human,unit=512,brief;
static int match(const char *p,const char *s){const char *star=NULL,*retry=NULL;while(*s){if(*p=='?'||*p==*s){p++;s++;}else if(*p=='*'){star=p++;retry=s;}else if(star){p=star+1;s=++retry;}else return 0;}while(*p=='*')p++;return !*p;}
static int walk(const char *path,int depth,int du,unsigned long long *total){
 char native[PATH_CAP],canonical[PATH_CAP],leaf[32],enc[100],child[PATH_CAP];CInfoPBRec pb;int e=resolve_ex(path,native,canonical,0);if(!e)e=info(native,&pb);if(e){error(path,e);return 1;}int directory=isdir(&pb),link=is_link(&pb),status=0;unsigned long long size=directory?0:(unsigned long)pb.hFileInfo.ioFlPyLen+(unsigned long long)(unsigned long)pb.hFileInfo.ioFlRPyLen;
 const char *base=strrchr(canonical,'/');base=base&&base[1]?base+1:canonical;
 if(!du&&(!pattern||match(pattern,base))&&(!kind||(kind=='d'&&directory)||(kind=='l'&&link)||(kind=='f'&&!directory&&!link))){say(path);say("\n");}
 if(directory&&depth<maxdepth){for(int index=1;;index++){e=cli_native_nth(native,index,leaf,&pb);if(e==fnfErr)break;if(e){error(path,e);status=1;break;}e=encode_name(leaf,enc,sizeof enc);if(!e)e=join_path(path,enc,child);if(e){error(path,e);status=1;break;}unsigned long long sub=0;int rc=walk(child,depth+1,du,&sub);if(rc==130)return 130;if(rc)status=rc;size+=sub;if(app_yield())return 130;}}
 else if(directory&&(du||!explicit_depth)){int check=cli_native_nth(native,1,leaf,&pb);if(!check){errsay(du?"du: depth limit reached; total is incomplete\n":"find: depth limit reached; traversal is incomplete\n");status=1;}else if(check!=fnfErr){error(path,check);status=1;}}
 if(du&&((directory&&(!summarize||!depth))||all||!depth)){char b[64];if(human)format_size(b,size,1);else snprintf(b,sizeof b,"%lu",(unsigned long)((size+unit-1)/unit));say(b);say("\t");say(path);say("\n");}*total=size;return output_error?1:status;
}
static void code4(unsigned long x,char *p){for(int i=0;i<4;i++){unsigned char c=x>>(24-8*i);p[i]=c>=32&&c<127?c:'.';}p[4]=0;}
static int describe(const char *path){char native[PATH_CAP],canonical[PATH_CAP],target[PATH_CAP],type[5],creator[5],buf[160];CInfoPBRec pb;int e=resolve_ex(path,native,canonical,0);if(!e)e=info(native,&pb);if(e){error(path,e);return 1;}if(!brief){say(path);say(": ");}
 if(isdir(&pb))say("HFS directory\n");else if(is_link(&pb)){e=link_target(native,target);if(e)return 1;say("Clarice symbolic link to ");say(target);say("\n");}else{code4(pb.hFileInfo.ioFlFndrInfo.fdType,type);code4(pb.hFileInfo.ioFlFndrInfo.fdCreator,creator);snprintf(buf,sizeof buf,"HFS file, type '%s', creator '%s', data %lu bytes, resource %lu bytes\n",type,creator,(unsigned long)pb.hFileInfo.ioFlLgLen,(unsigned long)pb.hFileInfo.ioFlRLgLen);say(buf);}return output_error?1:0;
}
static void usage(const char *name){if(!strcmp(name,"find"))say("find [path] [-name pattern] [-type f|d|l] [-maxdepth 0..8] [-print]\nWalk HFS directories without following symbolic links. Default path: .\n-name supports * and ? on the shell's encoded basename; quote patterns.\nPredicates combine with AND. [], -o, -exec and other expressions are unsupported.\nTraversal is capped at 8 levels; use -maxdepth to explicitly limit it.\n");else if(!strcmp(name,"du"))say("du [-ashk] [--] [path ...]\nAllocated data+resource fork space; default units 512 bytes, -k 1024, -h readable.\n-a includes files, -s gives argument totals. Links are not followed.\nHFS catalog/directory overhead is not assigned to individual folders.\nTraversal is bounded to 8 levels; deeper totals report an error.\n");else say("file [-b] [--] file ...\nDescribe HFS kind, symbolic target, type/creator and both fork sizes.\n-b omits the name. This is native metadata inspection, not libmagic content detection.\n");say("Status: 0 success, 1 file error, 2 usage, 130 interrupted.\n");}
int clarice_main(int argc,char **av){const char *name=strrchr(av[0],'/');name=name?name+1:av[0];if(argc==2&&!strcmp(av[1],"--help")){usage(name);return 0;}int i=1,status=0;
 if(!strcmp(name,"find")){const char *path=".";if(i<argc&&av[i][0]!='-')path=av[i++];for(;i<argc;i++){if(!strcmp(av[i],"-print"))continue;if(i+1>=argc){usage(name);return 2;}if(!strcmp(av[i],"-name")){pattern=av[++i];if(strchr(pattern,'[')||strchr(pattern,']')){usage(name);return 2;}}else if(!strcmp(av[i],"-type")){const char *v=av[++i];if(strlen(v)!=1||!strchr("fdl",*v)){usage(name);return 2;}kind=*v;}else if(!strcmp(av[i],"-maxdepth")){char *end;long n=strtol(av[++i],&end,10);if(*end||!*av[i]||n<0||n>8){usage(name);return 2;}maxdepth=n;explicit_depth=1;}else{usage(name);return 2;}}unsigned long long n;return walk(path,0,0,&n);}
 int du=!strcmp(name,"du");for(;i<argc&&av[i][0]=='-'&&av[i][1];i++){if(!strcmp(av[i],"--")){i++;break;}for(int j=1;av[i][j];j++){char c=av[i][j];if(du&&c=='a')all=1;else if(du&&c=='s')summarize=1;else if(du&&c=='h')human=1;else if(du&&c=='k')unit=1024;else if(!du&&c=='b')brief=1;else{usage(name);return 2;}}}
 if(du&&all&&summarize){usage(name);return 2;}if(i==argc){if(du){unsigned long long n;return walk(".",0,1,&n);}usage(name);return 2;}
 for(;i<argc;i++){unsigned long long n;int rc=du?walk(av[i],0,1,&n):describe(av[i]);if(rc==130)return rc;if(rc)status=rc;if(app_yield())return 130;}return status;
}
